return ['domain'=>'taxopress-pro','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'yo','project-id-version'=>'TaxoPress Pro 3.51.0','pot-creation-date'=>'2026-07-22T18:23:43+00:00','po-revision-date'=>'2026-07-22 18:38+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['TaxoPress Pro'=>'TaxoPress Pro','https://wordpress.org/plugins/simple-tags/'=>'https://wordpress.org/plugins/simple-tags/','TaxoPress allows you to create and manage Tags, Categories, and all your WordPress taxonomy terms.'=>'TaxoPress gba ọ laaye lati ṣẹda ati ṣakoso Tags, Categories, ati gbogbo awọn ọrọ taxonomy WordPress rẹ.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','License key'=>'Iwe-aṣẹ bọtini','Status'=>'Ipo','Your license key provides access to updates and support.'=>'Bọtini iwe-aṣẹ rẹ n pese iraye si awọn imudojuiwọn ati atilẹyin.','Activate License'=>'Mu Iwe-aṣẹ ṣiṣẹ','Synonyms'=>'Awọn ọrọ itumọ','This feature allows you to associate additional words with each term. For example, "website" can have synonyms such as "websites", "web site", and "web pages".'=>'Ẹya yii gba ọ laaye lati so awọn ọrọ afikun pọ pẹlu ọkọọkan ọrọ naa. Fun apẹẹrẹ, "website" le ni awọn ọrọ itumọ bii "websites", "web site", ati "web pages".','Linked Terms'=>'Awọn ọrọ ti a so pọ','This feature allows you to connect terms. When the main term or any of these terms are added to the post, all the other terms will be added also.'=>'Ẹya yii gba ọ laaye lati sopọ awọn ọrọ. Nigbati ọrọ pataki tabi eyikeyi ninu awọn ọrọ wọnyi ba ti fi kun si ifiweranṣẹ, gbogbo awọn ọrọ miiran yoo tun fi kun.','Shortcode Name'=>'Orukọ shortcode','Add'=>'Fi kun','Enter the shortcode name without [ ] or parameters.'=>'Tẹ orukọ shortcode laisi [ ] tabi awọn paramita.','Search Block'=>'Iwọn Wiwa','Search...'=>'Wa...','Search and select blocks.'=>'Wa ki o yan awọn bulọọki.','Element tag'=>'Tag eroja','Add Element'=>'Fi Ẹlẹmen ti a ṣe afikun','New Element'=>'Ẹlẹmen Tuntun','OpenAI is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'OpenAI jẹ iṣẹ ti ita ti o le ṣe ayẹwo akoonu rẹ ki o si daba awọn ọrọ to baamu. %1sTẹ nibi fun alaye%2s.','False'=>'Iro','True'=>'Otito','This will automatically add new terms from the OpenAI service. Before use, please test carefully using the preview feature.'=>'Eyi yoo ṣe afikun awọn ọrọ tuntun laifọwọyi lati iṣẹ OpenAI. Ṣaaju ki o to lo, jọwọ ṣe idanwo ni pẹkipẹki nipa lilo ẹya iworan.','Enable OpenAI'=>'Muu OpenAI ṣiṣẹ','API Key'=>'Bọtini API','Enter your OpenAI API Key.'=>'Tẹ bọtini API OpenAI rẹ.','gpt-3.5-turbo'=>'gpt-3.5-turbo','gpt-4o-mini'=>'gpt-4o-mini','gpt-4o'=>'gpt-4o','chatgpt-4o-latest'=>'chatgpt-4o-tuntun','gpt-5'=>'gpt-5','gpt-5-mini'=>'gpt-5-mini','gpt-5-nano'=>'gpt-5-nano','o3-mini'=>'o3-mini','o1-mini'=>'o1-mini','o1'=>'o1','OpenAI Models'=>'Àwọn Àmọ̀ràn OpenAI','Some models availability depends on your subscription and access.'=>'Diẹ ninu awọn awoṣe wa da lori ìforúkọsílẹ rẹ ati iraye si.','Show Term Post Count'=>'Fihan Iye Ifiweranṣẹ Ọjọgbọn','This will show the number of posts attached to the terms.'=>'Eyi yoo fihan nọmba awọn ifiweranṣẹ ti o so mọ awọn ọrọ-ọrọ.','Cache Results'=>'Kẹ́kẹ́ Ẹ̀rí','By caching the results locally, new API requests will not be made unless the post title or content changes. This saves API usage.'=>'Nipa fipamọ awọn abajade ni agbegbe, awọn ibeere API tuntun kii yoo ṣe ayẹwo ayafi ti akọle ifiweranṣẹ tabi akoonu ba yipada. Eyi n fipamọ lilo API.','OpenAI Prompt (Beta)'=>'OpenAI Prompt (Beta)','%1s Click here for prompt documentation. %2s'=>'%1s Tẹ nibi fun iwe afọwọkọ. %2s','OpenAI Max Tokens'=>'OpenAI Max Tokens','Maximum tokens for OpenAI response. You can increase this when using {site} placeholder with many terms.'=>'Awọn ọkọ ayọkẹlẹ ti o pọ julọ fun idahun OpenAI. O le pọ si eyi nigbati o ba nlo {site} aaye pẹlu ọpọlọpọ awọn ọrọ-ọrọ.','IBM Watson is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'IBM Watson jẹ iṣẹ ita ti o le ṣe àyẹ̀wò akoonu rẹ ati ṣedasilẹ awọn ọrọ-ọrọ to yẹ. %1sTẹ nibi fun alaye%2s.','This will automatically add new terms from the IBM Watson service. Before use, please test carefully using the preview feature.'=>'Eyi yoo ṣafikun awọn ọrọ-ọrọ tuntun laifọwọyi lati iṣẹ IBM Watson. Ṣaaju ki o to lo, jọwọ ṣe idanwo ni pẹkipẹki nipa lilo ẹya iworan.','Enable IBM Watson'=>'Mu IBM Watson ṣiṣẹ','API URL'=>'API URL','Enter your IBM Watson API URL.'=>'Tẹ URL API IBM Watson rẹ.','Enter your IBM Watson API Key.'=>'Tẹ bọtini API IBM Watson rẹ.','This integration is no longer actively supported. If you still need to use it, you can enable it in the Legacy AI Sources settings.'=>'Iṣọpọ yii ko ni atilẹyin ni iṣe mọ. Ti o ba tun nilo lati lo, o le mu u ṣiṣẹ ni awọn eto Legacy AI Sources.','Dandelion is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'Dandelion jẹ iṣẹ ita ti o le ṣe àyẹ̀wò akoonu rẹ ati ṣedasilẹ awọn ọrọ-ọrọ to yẹ. %1sTẹ nibi fun alaye%2s.','This will automatically add new terms from the Dandelion service. Before use, please test carefully using the preview feature.'=>'Eyi yoo ṣafikun awọn ọrọ-ọrọ tuntun laifọwọyi lati iṣẹ Dandelion. Ṣaaju ki o to lo, jọwọ ṣe idanwo ni pẹkipẹki nipa lilo ẹya iworan.','Enable Dandelion'=>'Mu Dandelion ṣiṣẹ','API Token'=>'API Token','Enter your Dandelion API Key.'=>'Tẹ bọtini API Dandelion rẹ.','API Confidence Value'=>'API Confidence Value','Choose a value between 0 and 1. A high value such as 0.8 will provide a few, accurate suggestions. A low value such as 0.2 will produce more suggestions, but they may be less accurate.'=>'Yan iye laarin 0 ati 1. Iye giga bii 0.8 yoo pese diẹ, awọn iṣeduro to pe. Iye kekere bii 0.2 yoo mu ọpọlọpọ awọn iṣeduro wa, ṣugbọn wọn le jẹ kere si deede.','LSEG / Refinitiv is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'LSEG / Refinitiv jẹ iṣẹ ita ti o le ṣe ayẹwo akoonu rẹ ki o si daba awọn ọrọ to yẹ. %1sTẹ nibi fun alaye%2s.','This will automatically add new terms from the LSEG / Refinitiv service. Before use, please test carefully using the preview feature.'=>'Eyi yoo fi awọn ọrọ tuntun kun laifọwọyi lati inu iṣẹ LSEG / Refinitiv. Ṣaaju ki o to lo, jọwọ ṣe idanwo ni pẹkipẹki nipa lilo ẹya iworan.','Enable LSEG / Refinitiv'=>'Mu LSEG / Refinitiv ṣiṣẹ','Enter your LSEG / Refinitiv API Key.'=>'Tẹ bọtini API LSEG / Refinitiv rẹ.','Regular Expressions'=>'Awọn Ilana Aiyipada','Use Regular Expressions to change how Auto Terms analyzes your posts. This works for terms added when posts are saved or added via the "Schedule" feature.'=>'Lo Awọn Ilana Aiyipada lati yi bi Auto Terms ṣe n ṣe itupalẹ awọn ifiweranṣẹ rẹ. Eyi ṣiṣẹ fun awọn ọrọ ti a fi kun nigbati awọn ifiweranṣẹ ba wa ni fipamọ tabi fi kun nipasẹ ẹya "Schedule".','Regex code'=>'Koodu Regex','Example: <code>/\\b({term})\\b/i</code> will match the whole word while <code>/({term})/i</code> will match at any location even if it\'s part of another word. <code>{term}</code> will be replaced with the term name before the regex action.'=>'Apẹẹrẹ: <code>/\\b({term})\\b/i</code> yoo ba gbogbo ọrọ mu nigba ti <code>/({term})/i</code> yoo ba ni ipo eyikeyi paapaa ti o ba jẹ apakan ti ọrọ miiran. <code>{term}</code> yoo rọpo pẹlu orukọ ọrọ ṣaaju iṣe regex.','Auto Terms successfully copied.'=>'Auto Terms ti daakọ ni aṣeyọri.','Copy'=>'Daakọ','Hourly'=>'Ni wakati','Daily'=>'Ni ọjọ','Primary Term Name'=>'Orukọ Ọrọ pataki','Secondary Term Name'=>'Orukọ Ọrọ keji','Primary Term Taxonomy'=>'Taxonomy Ọrọ pataki','Secondary Term Taxonomy'=>'Taxonomy Ọrọ keji','Primary Term Post Count'=>'Iye Ifiweranṣẹ Ọrọ pataki','Secondary Term Post Count'=>'Iye Fún Àkóónú Ọ̀rọ̀ Kejì','Add primary term to posts with secondary term'=>'Fi àkọ́ọ́rẹ̀ akọkọ sí àwọn àkóónú pẹ̀lú àkọ́ọ́rẹ̀ kejì','Add secondary term to posts with primary term'=>'Fi àkọ́ọ́rẹ̀ kejì sí àwọn àkóónú pẹ̀lú àkọ́ọ́rẹ̀ akọkọ','Delete Relationship'=>'Pa Ìbáṣepọ̀','Taxonomy'=>'taxonomy','Filter'=>'Filẹ́tà','Error deleting linked term relationship.'=>'Aṣiṣe mímu ìbáṣepọ̀ àkọ́ọ́rẹ̀ tó so pọ̀.','Linked terms deleted successfully.'=>'Àkọ́ọ́rẹ̀ tó so pọ̀ ti pa dáadáa.','Linked term deleted successfully.'=>'Àkọ́ọ́rẹ̀ tó so pọ̀ ti pa dáadáa.','%d posts updated successfully.'=>'%d àkóónú ti ṣe àtúnṣe dáadáa.','0 post update.'=>'0 àkóónú àtúnṣe.','No linked terms found.'=>'Kò sí àkọ́ọ́rẹ̀ tó so pọ̀ tí a rí.','Number of items per page'=>'Iye àwọn nkan ní ojú ìwé kọọkan','This feature allows you to connect terms. When the primary or secondary term is added to a post, the other term can be added also.'=>'Ẹ̀ka yìí jẹ́ kí o so àwọn àkọ́ọ́rẹ̀ pọ̀. Nigbati a ba fi àkọ́ọ́rẹ̀ akọkọ tàbí kejì sí àkóónú, a tún lè fi àkọ́ọ́rẹ̀ míì kún un.','Search results for &#8220;%s&#8221;'=>'Àbájáde ìwádìí fún &#8220;%s&#8221;','Search Terms'=>'Àkọ́ọ́rẹ̀ ìwádìí','Description here.'=>'Àpejuwe nibi.','Start typing to choose existing terms.'=>'Bẹrẹ sí kọ́ láti yan àwọn àkọ́ọ́rẹ̀ tí ó wà.','These terms are linked to the main term. When the primary or secondary term is added to a post, the other term can be added also.'=>'Àwọn àkọ́ọ́rẹ̀ yìí jẹ́ ti àkọ́ọ́rẹ̀ pàtàkì. Nigbati a ba fi àkọ́ọ́rẹ̀ akọkọ tàbí kejì sí àkóónú, a tún lè fi àkọ́ọ́rẹ̀ míì kún un.','The superscript %1$s indicates the linked term being the primary term, while %2$s is shown when the linked term is the secondary term. You can delete the relationship and re-add it from your preferred term edit screen to make them the primary term.'=>'Ìṣàpẹẹrẹ %1$s tọ́ka si àkọ́ọ́rẹ̀ tó so pọ̀ tí ó jẹ́ àkọ́ọ́rẹ̀ akọkọ, nígbà tí %2$s jẹ́ afihan nigba tí àkọ́ọ́rẹ̀ tó so pọ̀ jẹ́ àkọ́ọ́rẹ̀ kejì. O le pa ìbáṣepọ̀ náà ki o sì tún fi i kún un láti ojú ìtúnṣe àkọ́ọ́rẹ̀ rẹ tí o fẹ́ láti jẹ́ kí wọ́n jẹ́ àkọ́ọ́rẹ̀ akọkọ.','Term Synonyms'=>'Orukọ Awọn Ẹya','Type the synonym name (comma-separated) and then click Enter or Return.'=>'Tẹ orukọ ẹya (pẹlu awọn koma) ki o si tẹ Enter tabi Return.','If TaxoPress scans your content and finds a synonym, it will act as if it has found the main term.'=>'Ti TaxoPress ba ṣe ayẹwo akoonu rẹ ki o si ri ẹya, yoo ṣiṣẹ bi ẹni pe o ti ri ọrọ pataki.','This synonym can\'t be added because %1$s is a term on this site.'=>'Ẹya yii ko le ṣe afikun nitori %1$s jẹ ọrọ lori aaye yii.','These synonyms can\'t be added because %1$s are terms on this site.'=>'Awọn ẹya wọnyi ko le ṣe afikun nitori %1$s jẹ awọn ọrọ lori aaye yii.','This synonym can\'t be added because %1$s is already added to another term.'=>'Ẹya yii ko le ṣe afikun nitori %1$s ti wa ni afikun si ọrọ miiran.','These synonyms can\'t be added because %1$s are already added to another term.'=>'Awọn ẹya wọnyi ko le ṣe afikun nitori %1$s ti wa ni afikun si ọrọ miiran.','%1$s can\'t be added as a tag because %2$s is already used as a synonym.'=>'%1$s ko le ṣe afikun gẹgẹbi aami nitori %2$s ti wa ni lilo gẹgẹbi ẹya.','Request status.'=>'Ipo ibeere.','Security error. Kindly reload this page and try again'=>'Aṣiṣe aabo. Jọwọ tun gbe oju-iwe yii ki o si gbiyanju lẹẹkansi','Default'=>'Aiyipada','Dropdown'=>'Iṣakojọpọ','Checkbox'=>'Aami-ibaraẹnisọrọ','Taxonomy Display'=>'Ifihan Taxonomy','Enable IBM Watson integration'=>'Mu iṣọpọ IBM Watson ṣiṣẹ','Show IBM Watson as an AI source for Auto Terms'=>'Fihan IBM Watson gẹgẹbi orisun AI fun Awọn Ọrọ Aifọwọyi','Enable Dandelion integration'=>'Mu iṣọpọ Dandelion ṣiṣẹ','Show Dandelion as an AI source for Auto Terms.'=>'Fihan Dandelion gẹgẹbi orisun AI fun Awọn Ọrọ Aifọwọyi.','Enable LSEG/Refinitiv integration'=>'Mu iṣọpọ LSEG/Refinitiv ṣiṣẹ','Show LSEG/Refinitiv as an AI source for Auto Terms'=>'Fihan LSEG/Refinitiv gẹgẹbi orisun AI fun Awọn Ọrọ Aifọwọyi','Term successfully copied with metadata.'=>'Ìpè ti a daakọ́ pẹ̀lú àlàyé aṣà.','Copy with Metadata'=>'Daakọ́ pẹ̀lú Àlàyé']];